SELECT *
FROM er.dataset_neuron
WHERE raw_metadata = 'hemibrain:1688868386';

SELECT c.relname AS table_name, t.tgname AS trigger_name, pg_get_triggerdef(t.oid) AS definition
FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
WHERE NOT t.tgisinternal AND c.relnamespace = 'cc'::regnamespace;

SELECT annotation_key, annotation_value, valid_from_release, valid_until_release,
       recorded_from, recorded_until
FROM annotation_history(find_neuron('hemibrain', '1688868386'));

SELECT * FROM annotation
WHERE dataset_neuron_id = find_neuron('hemibrain', '1688868386')
  AND valid_rel @> 3 AND tx @> now();

SELECT dataset_neuron_id, source_neuron_id, metadata_doc_id AS mongodb_id
FROM dataset_neuron
WHERE metadata_doc_id = 'hemibrain:1688868386';

INSERT INTO lab.connection (release_id, dataset_id, pre_neuron_id, post_neuron_id, synapse_count)
SELECT release_id, dataset_id, 999999999999, 999999999998, 3
FROM lab.release LIMIT 1;

BEGIN;
UPDATE lab.neuron SET cell_type = 'kept' WHERE source_neuron_id = 'my-neuron-1';
SAVEPOINT before_delete;
DELETE FROM lab.connection;               -- oops: every connection
ROLLBACK TO SAVEPOINT before_delete;      -- undone
COMMIT;
SELECT (SELECT count(*) FROM lab.connection) AS connections_still_there,
       (SELECT cell_type FROM lab.neuron WHERE source_neuron_id = 'my-neuron-1') AS kept_change;

DELETE FROM lab.neuron WHERE source_neuron_id = 'my-neuron-1' RETURNING neuron_id;
SELECT change_id, table_name, operation, coalesce(old_row, new_row) AS row_data, changed_by, changed_at
FROM lab.change_log
ORDER BY change_id DESC
LIMIT 10;

CREATE TABLE lab.neuron_note (
    note_id    integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    neuron_id  bigint NOT NULL REFERENCES lab.neuron ON DELETE CASCADE,
    note       text NOT NULL CHECK (note <> ''),
    created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO lab.neuron_note (neuron_id, note)
SELECT neuron_id, 'checked by the evaluator' FROM lab.neuron ORDER BY neuron_id LIMIT 3;
SELECT * FROM lab.neuron_note;

ALTER TABLE lab.neuron ADD COLUMN IF NOT EXISTS reviewed boolean NOT NULL DEFAULT false;
UPDATE lab.neuron SET reviewed = true WHERE cell_type IS NOT NULL;
SELECT reviewed, count(*) FROM lab.neuron GROUP BY reviewed;

CREATE INDEX IF NOT EXISTS connection_synapses_idx ON lab.connection (synapse_count);
ANALYZE lab.connection;
EXPLAIN SELECT * FROM lab.connection WHERE synapse_count > 500;

CREATE OR REPLACE VIEW lab.strongest_partner AS
SELECT DISTINCT ON (c.release_id, c.pre_neuron_id)
       c.release_id, c.pre_neuron_id, c.post_neuron_id, c.synapse_count
FROM lab.connection c
ORDER BY c.release_id, c.pre_neuron_id, c.synapse_count DESC;
SELECT * FROM lab.strongest_partner ORDER BY synapse_count DESC LIMIT 10;

INSERT INTO cc.dataset (code, name, organism)
VALUES ('evaluator_test', 'Inserted during a trial', 'Drosophila melanogaster')
RETURNING dataset_id, code, name, created_at;

UPDATE cc.dataset
SET description = 'edited during a trial'
RETURNING code, description;
